<template><div v-if="review"><div class="notice" :class="review.ok?'success':'danger'">{{review.ok?'预检通过，请核对部署范围后确认执行。':'预检未通过，请修正配置或环境后重试。'}}</div><dl class="facts" style="margin-bottom:20px"><dt>环境名称</dt><dd>{{review.environment}}</dd><dt>发行版本</dt><dd>{{review.packageName}} {{review.version}}</dd><dt>操作类型</dt><dd>{{review.upgrade?'兼容升级 / 配置变更':'全新独立部署'}}</dd></dl><DataTable :rows="review.checks||[]" :columns="columns" :searchable="false" row-key="name"><template #status="{row}"><StateBadge :status="row.status"/></template><template #detail="{row}"><template v-if="typeof row.detail==='object'"><span v-for="(value,key) in row.detail" :key="key" style="display:block">{{capacityLabels[key]||key}}：{{key.endsWith('Bytes')?bytes(value):value}}</span></template><template v-else>{{row.detail}}</template></template></DataTable><details v-if="review.components?.length" style="margin-top:20px"><summary>查看依赖顺序（{{review.components.length}} 个组件）</summary><ol><li v-for="component in review.components" :key="component.id" style="padding:5px">{{component.id}} <small>依赖：{{component.dependsOn?.join(', ')||'无'}}</small></li></ol></details></div></template>
<script setup>
import DataTable from '../ui/DataTable.vue';import StateBadge from '../ui/StateBadge.vue';import {bytes} from '../../utils/format';defineProps({review:Object});const columns=[{key:'name',label:'检查项'},{key:'status',label:'结果'},{key:'detail',label:'检查详情'}],capacityLabels={availableMemoryBytes:'可用内存',requiredMemoryBytes:'新增内存需求',declaredMemoryBytes:'声明内存预算',reusedResidentBytes:'复用组件内存'};
</script>
